"""Write docs/metrics.md, the metrics reference, from the registry's catalog.

    uv run python scripts/metrics_doc.py

``tests/test_metrics_doc.py`` fails when the page and the registry disagree; run this
to bring the page up to date.
"""

from pathlib import Path

from teehr_core.metrics.catalog import FAMILIES, PARAMETERS, UNIT_KINDS, catalog
from teehr_core.metrics.units import UnitKind

PAGE = Path(__file__).resolve().parents[1] / "docs" / "metrics.md"

INTRO = """\
# Metrics

<!-- Generated by scripts/metrics_doc.py from the metric registry: edit those, not this. -->

Every metric an evaluation spec can compute, from teehr-core's metric registry. Name a metric
in an `aggregate` stage by its canonical name or an alias; results always carry the canonical
name (so `kge` gives a `kling_gupta_efficiency` column).

```yaml
aggregate:
  - group_by: [primary_series_key]
    metrics:
      - count
      - kge                                            # an alias
      - {name: hits, threshold: {value: 1000, unit: "[cft_i]/s"}}
      - {name: nse, transform: log}                    # on log values
```

The [spec guide](spec/README.md#metric-options) has every metric option (`transform`, `as`,
thresholds, normalizers, `of` for later stages); the parameters below are the ones particular
metrics take.

In the tables:

- **Unit**: what the result is in. Values are compared in the evaluation unit (`output.unit`,
  default the primary dataset's), so an error such as RMSE is in that unit, and an efficiency
  has none.
- **Merges**: whether the metric can be computed from merged state (running sums kept per
  group and month). Evaluations whose metrics all merge can rerun incrementally, recomputing
  only the months whose data changed, and in shards; one that doesn't merge makes every run
  recompute all pairs at once.
- **Parameters**: **bold** ones are required.
"""


def _code(names: list[str]) -> str:
    return ", ".join(f"`{n}`" for n in names)


def _cell(text: str) -> str:
    return " ".join(text.split()).replace("|", "\\|")


def render() -> str:
    metrics = catalog()
    lines = [INTRO]
    lines.append(f"{len(metrics)} metrics; {sum(m['merges'] for m in metrics)} merge.\n")
    lines.append("## Parameters\n")
    lines.append("| Parameter | What it is | Default |")
    lines.append("| --- | --- | --- |")
    for name, (what, default) in PARAMETERS.items():
        lines.append(f"| `{name}` | {_cell(what)} | {default} |")
    lines.append("")
    lines.append("## Result units\n")
    lines.append("| Unit | Meaning |")
    lines.append("| --- | --- |")
    for kind in UnitKind:
        lines.append(f"| `{kind.value}` | {UNIT_KINDS[kind]} |")
    lines.append("")
    for family, heading in FAMILIES.items():
        rows = [m for m in metrics if m["family"] == family]
        if not rows:
            continue
        lines.append(f"## {heading}\n")
        lines.append("| Metric | Aliases | Definition | Parameters | Unit | Merges |")
        lines.append("| --- | --- | --- | --- | --- | --- |")
        for m in rows:
            params = ", ".join(
                f"**`{p}`**" if p in m["required"] else f"`{p}`" for p in m["parameters"]
            )
            reads = f" Reads `{'`, `'.join(m['reads'])}`." if m["reads"] else ""
            lines.append(
                f"| `{m['name']}` | {_code(m['aliases'])} | {_cell(m['description'])}{reads} "
                f"| {params} | `{m['unit']}` | {'yes' if m['merges'] else '**no**'} |"
            )
        lines.append("")
    return "\n".join(lines)


if __name__ == "__main__":
    PAGE.write_text(render())
    print(f"wrote {PAGE}")
